        // Check if dx is divisible by x
        if (dx % x == 0) {
            long u = dx / x;
            // Check if dy is divisible by y
            if (dy % y == 0) {
                long v = dy / y;
                // Check if u and v have the same parity
                if ((u % 2 == 0 && v % 2 == 0) || (u % 2 != 0 && v % 2 != 0)) {
                    // Handle negative modulo in Java
                    long uMod = ((u % 2) + 2) % 2;
                    long vMod = ((v % 2) + 2) % 2;
                    if (uMod == vMod) {
                        possible = true;
                    }
                }
            }
        }

        System.out.println(possible ? "YES" : "NO");
    }
}
