        long q = dy / y;

        // Check if p and q have the same parity
        if ((p % 2 == 0 && q % 2 == 0) || (p % 2 != 0 && q % 2 != 0)) {
            // Need to handle negative modulo in Java
            long pParity = ((p % 2) + 2) % 2;
            long qParity = ((q % 2) + 2) % 2;
